      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O acúmulo prolongado de água produzida em ambientes fechados é associado ao risco de proliferação de bactérias redutoras de sulfato, com consequente geração de H2S.",
          "trechos": [
            "E319f1c5630174683:0:695"
          ],
          "condicoes": [
            "água produzida acumulada por longos períodos",
            "ambientes fechados"
          ],
          "limites": [
            "o trecho descreve risco associado, não quantifica frequência nem severidade",
            "o contexto parece ligado a tanques de água produzida, não a todos os sistemas offshore"
          ]
        },
        {
          "proposicao": "Diante da toxicidade e corrosividade do H2S, o texto indica necessidade de facilidades para monitoramento desse gás e para aplicação de biocidas.",
          "trechos": [
            "E319f1c5630174683:0:695"
          ],
          "condicoes": [
            "presença potencial de H2S decorrente de atividade microbiológica"
          ],
          "limites": [
            "o trecho não detalha método de monitoramento, biocida, dosagem ou periodicidade"
          ]
        },
        {
          "proposicao": "É citada diretriz da Petrobras segundo a qual tanques que manuseiam água produzida e água segregada devem ser preparados para ambiente corrosivo e prever facilidades para controle da geração de H2S.",
          "trechos": [
            "E319f1c5630174683:695:1393"
          ],
          "condicoes": [
            "tanques que irão manusear água produzida e água segregada"
          ],
          "limites": [
            "trata-se de referência a diretriz interna mencionada no texto, sem edição, data completa ou confirmação de vigência",
            "não demonstra aplicabilidade geral a todas as instalações offshore no Brasil"
          ]
        }
      ]
    },
