          ]
        },
        {
          "proposicao": "O trecho reúne referências operacionais e define FPSO como unidade flutuante de produção, armazenagem e transferência de óleo.",
          "trechos": [
            "Ed85bfe4e07ff8b16:2086:2481"
          ],
          "condicoes": [],
